fun Route.ordersPage(orderService: OrderService) {
    get("/orders") {
        val page = orderService.list(call.request.queryParameters["page"] ?: "1")
        call.respondText(renderOrders(page), ContentType.Text.Html)   // view selection
    }
}

fun Application.module() {
    install(RoutingRoot) { ordersPage(orderService) }
}
